import pytest

from app import audit as audit_mod
from app.errors import AppError, ValidationError
from app.features.refunds import refund_amount


@pytest.fixture(autouse=True)
def clear_audit():
    audit_mod.EVENTS.clear()
    yield
    audit_mod.EVENTS.clear()


def test_no_fee():
    assert refund_amount("12.50", 0) == 1250


def test_full_fee_refunds_nothing():
    assert refund_amount("12.50", 10000) == 0


def test_fee_is_floored():
    # 1250 * 250 // 10000 = 31 (31.25 floored), refund = 1219
    assert refund_amount("12.50", 250) == 1219


def test_dollar_sign_and_short_decimal():
    assert refund_amount("$12.5", 0) == 1250


def test_records_audit_event():
    refund_amount("1.00", 100)
    assert audit_mod.EVENTS == [
        {
            "event": "refund_calculated",
            "price_cents": 100,
            "fee_bps": 100,
            "refund_cents": 99,
        }
    ]


@pytest.mark.parametrize("fee", [-1, 10001, 2.5, "100", None, True])
def test_bad_fee_raises(fee):
    with pytest.raises(ValidationError):
        refund_amount("1.00", fee)
    assert audit_mod.EVENTS == []


@pytest.mark.parametrize("price", ["abc", "", "1.234", "-1.00", "1,00", None])
def test_bad_price_raises(price):
    with pytest.raises(ValidationError):
        refund_amount(price, 100)
    assert audit_mod.EVENTS == []


def test_errors_are_app_errors():
    assert issubclass(ValidationError, AppError)

